function change(amount: number, coins: number[]): number {
  // dp[i] will store the number of ways to make amount i
  let dp: number[] = new Array(amount + 1).fill(0);
  // Base case: there's one way to make amount 0 (using no coins)
  dp[0] = 1;

  // Iterate through the coins in reverse order to avoid duplicate combinations
  for (let i = coins.length - 1; i >= 0; i--) {
    // Create a new DP array to store the updated counts for the current coin
    const nextDP: number[] = new Array(amount + 1).fill(0);
    // Base case for the new DP array: there's one way to make amount 0
    nextDP[0] = 1;

    // Iterate through the amounts from 1 to the target amount
    for (let a = 1; a <= amount; a++) {
      // Initialize the number of ways to make amount 'a' using the values from the previous DP array
      // This essentially means we're not using the current coin 'coins[i]'
      nextDP[a] = dp[a];

      // If the current coin's value is less than or equal to the current amount
      if (a - coins[i] >= 0) {
        // Add the number of ways to make the remaining amount (a - coins[i]) using the current coin
        nextDP[a] += nextDP[a - coins[i]];
      }
    }

    // Update the main DP array with the values from the new DP array for the next iteration
    dp = nextDP;
  }

  // Return the number of ways to make the target amount using the given coins
  return dp[amount];
}

