        // dp[i] will store the number of ways to make the amount i
        int[] dp = new int[amount + 1];

        // Base case: There is one way to make amount 0 (using no coins)
        dp[0] = 1;

        // Iterate through each coin denomination in reverse order.
        // This approach ensures that we only count distinct combinations.
        for (int i = coins.length - 1; i >= 0; i--) {
            // nextDP will store the updated counts for the current coin
            int[] nextDP = new int[amount + 1];

            // Base case for the nextDP array: There is one way to make amount 0
            nextDP[0] = 1;

            // Iterate through each amount from 1 to the target amount
            for (int a = 1; a <= amount; a++) {
                // The number of ways to make amount 'a' without using the current coin
                nextDP[a] = dp[a];

                // If the current coin's value is less than or equal to the current amount,
                // we can include it in the combination.
                if (a - coins[i] >= 0) {
                    // Add the number of ways to make the remaining amount (a - coins[i])
                    // using the current coin to the number of ways to make amount 'a'.
                    nextDP[a] += nextDP[a - coins[i]];
                }
            }

            // Update dp array with the new counts for the current coin.
            dp = nextDP;
        }

        // Return the number of ways to make the target amount.
        return dp[amount];
    }
}

