public:
    int longestCommonSubsequence(string text1, string text2) {
        // Get the lengths of the two input strings.
        int m = text1.length(), n = text2.length();

        // Initialize a 2D vector 'dp' of size (m+1) x (n+1) with all elements set to 0.
        // dp[i][j] will store the length of the longest common subsequence of text1[0...i-1] and text2[0...j-1].
        vector < vector < int >> dp(m + 1, vector<int>(n + 1, 0));

        // Iterate through the strings using nested loops.
        // The outer loop iterates from 1 to m (inclusive), representing the prefixes of text1.
        for (int i = 1; i <= m; i++) {
            // The inner loop iterates from 1 to n (inclusive), representing the prefixes of text2.
            for (int j = 1; j <= n; j++) {
                // Check if the characters at the current positions in text1 and text2 are equal.
                if (text1[i - 1] == text2[j - 1]) {
                    // If the characters are equal, it means we can extend the LCS found so far.
                    // dp[i][j] is updated to be the LCS of the prefixes without the current characters (dp[i-1][j-1]) plus 1.
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    // If the characters are not equal, it means we cannot extend the LCS by including both characters.
                    // We take the maximum of the LCS found by either excluding the current character from text1 (dp[i-1][j])
                    // or excluding the current character from text2 (dp[i][j-1]).
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // After the loops complete, dp[m][n] contains the length of the LCS of the entire strings text1 and text2.
        return dp[m][n];
    }
};

