// Function to find the length of the longest increasing subsequence
function lengthOfLIS(nums: number[]): number {
    const n = nums.length;

    // Initialize an array to store the length of LIS ending at each index.
    // Every element is an LIS of length 1 by itself.
    const LIS: number[] = new Array(n).fill(1);

    // Iterate backwards through the array
    for (let i = n - 1; i >= 0; i--) {
        // For each element, iterate through the elements after it
        for (let j = i + 1; j < n; j++) {
            // If the current element is less than a subsequent element,
            // it can be part of an increasing subsequence.
            if (nums[i] < nums[j]) {
                // Update the LIS length at index i if including nums[j]
                // results in a longer increasing subsequence.
                LIS[i] = Math.max(LIS[i], 1 + LIS[j]);
            }
        }
    }

    // Return the maximum value in the LIS array, which is the length
    // of the longest increasing subsequence in the input array.
    return Math.max(...LIS);
}

