public static class Solution {
    public int lengthOfLIS(int[] nums) {
        int n = nums.length;

        // Initialize LIS array, each element initially representing a subsequence of length 1
        int[] LIS = new int[n];
        for (int i = 0; i < n; i++) {
            LIS[i] = 1;
        }

        // Iterate backwards through the array. This is a crucial step in the DP approach.
        for (int i = n - 1; i >= 0; i--) {
            // For each element, iterate through the elements after it
            for (int j = i + 1; j < n; j++) {
                // If nums[i] is less than nums[j], it can be added to an increasing subsequence ending at nums[j]
                if (nums[i] < nums[j]) {
                    // Update LIS[i] to be the maximum of its current value and 1 + LIS[j].
                    // This means we're checking if adding nums[i] to the subsequence ending at nums[j]
                    // results in a longer increasing subsequence.
                    LIS[i] = Math.max(LIS[i], 1 + LIS[j]);
                }
            }
        }

        // Find the maximum value in the LIS array, which represents the length of the longest increasing subsequence
        int maxLength = 0;
        for (int i = 0; i < n; i++) {
            maxLength = Math.max(maxLength, LIS[i]);
        }

        return maxLength;
    }
}

