class Solution {
public:
    int lengthOfLIS(vector<int> & nums) {
        // 'tails' will store the smallest tail of all increasing subsequences with length i+1 at tails[i].
        // It's maintained in increasing order.
        vector<int> tails;

        // Iterate through each number in the input 'nums'.
        for (int num : nums) {
            // Use binary search (lower_bound) to find the smallest tail in 'tails' that is greater than or equal to the current number 'num'.
            auto it = lower_bound(tails.begin(), tails.end(), num);

            // If 'num' is greater than all tails in 'tails' (i.e., 'it' reaches the end of 'tails').
            if (it == tails.end()) {
                // It means we can extend the longest increasing subsequence found so far by appending 'num'.
                tails.push_back(num);
            } else {
                // If 'num' is not greater than all tails, it means there is a tail that is greater than or equal to 'num'.
                // We replace that tail with 'num' because 'num' allows us to potentially form a longer increasing subsequence later.
                // Replacing with a smaller number maintains the increasing property of the 'tails' vector and allows for potentially longer subsequences.
                *it = num;
            }
        }

        // The size of 'tails' is the length of the longest increasing subsequence.
        return tails.size();
    }
};

