function minDistance(word1: string, word2: string): number {
    const m = word1.length;
    const n = word2.length;

    // Create DP table: (m+1) x (n+1)
    // cache[i][j] stores the edit distance between word1[i:] and word2[j:]
    const cache: number[][] = Array.from({ length: m + 1 }, () =>
        new Array(n + 1).fill(Infinity)
    );

    // Base case: If word1 is empty (i.e., we've processed all of word1)
    // The edit distance is the number of characters remaining in word2, which require insertions
    for (let j = 0; j <= n; j++) {
        cache[m][j] = n - j;
    }

    // Base case: If word2 is empty (i.e., we've processed all of word2)
    // The edit distance is the number of characters remaining in word1, which require deletions
    for (let i = 0; i <= m; i++) {
        cache[i][n] = m - i;
    }

    // Fill DP table from bottom-right to top-left
    // Iterate through the strings in reverse order
    for (let i = m - 1; i >= 0; i--) {
        for (let j = n - 1; j >= 0; j--) {
            // If the characters at the current positions match
            if (word1[i] === word2[j]) {
                // No operation needed, so the edit distance is the same as for the remaining substrings
                cache[i][j] = cache[i + 1][j + 1];
            } else {
                // Characters don't match, so we need to perform an operation (insert, delete, or replace)
                // We choose the operation that results in the minimum edit distance
                cache[i][j] =
                    1 +
                    Math.min(
                        cache[i + 1][j],     // delete: delete word1[i] and compare word1[i+1:] with word2[j:]
                        cache[i][j + 1],     // insert: insert word2[j] before word1[i] and compare word1[i:] with word2[j+1:]
                        cache[i + 1][j + 1]  // replace: replace word1[i] with word2[j] and compare word1[i+1:] with word2[j+1:]
                    );
            }
        }
    }

    // The minimum edit distance between word1 and word2 is stored in cache[0][0]
    return cache[0][0];
}

