public static class Solution {
    public int minDistance(String word1, String word2) {
        int m = word1.length(); // Length of word1
        int n = word2.length(); // Length of word2

        // Create DP table to store edit distances between prefixes of word1 and word2.
        // cache[i][j] will store the edit distance between word1[i:] and word2[j:].
        int[][] cache = new int[m + 1][n + 1];

        // Base case: if word1 is empty, the edit distance is the number of insertions needed to get word2 (or its suffix).
        for (int j = 0; j <= n; j++) {
            cache[m][j] = n - j; // If word1 is empty, the cost is the remaining characters in word2.
        }

        // Base case: if word2 is empty, the edit distance is the number of deletions needed to get word1 (or its suffix).
        for (int i = 0; i <= m; i++) {
            cache[i][n] = m - i; // If word2 is empty, the cost is the remaining characters in word1.
        }

        // Fill DP table from bottom-right to top-left.
        // This ensures that when calculating cache[i][j], we already have the values of cache[i+1][j], cache[i][j+1], and cache[i+1][j+1].
        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                // If the characters at the current positions are equal, no operation is needed.
                if (word1.charAt(i) == word2.charAt(j)) {
                    cache[i][j] = cache[i + 1][j + 1]; // Inherit the edit distance from the subproblem without these characters.
                } else {
                    // If the characters are different, we need to perform one of the three operations (insert, delete, replace).
                    // We choose the operation that results in the minimum edit distance.
                    cache[i][j] = 1 + Math.min(
                        cache[i + 1][j],     // delete: delete word1[i] and calculate the edit distance between word1[i+1:] and word2[j:]
                        Math.min(cache[i][j + 1],     // insert: insert word2[j] into word1 and calculate the edit distance between word1[i:] and word2[j+1:]
                        cache[i + 1][j + 1])  // replace: replace word1[i] with word2[j] and calculate the edit distance between word1[i+1:] and word2[j+1:]
                    );
                }
            }
        }

        return cache[0][0]; // The edit distance between word1 and word2 is stored in cache[0][0].
    }
}

