class Solution {
public:
    int minDistance(string word1, string word2) {
        int m = word1.length(), n = word2.length();
        // dp[i][j] stores the edit distance between word1[0...i-1] and word2[0...j-1]
        vector < vector < int >> dp(m + 1, vector<int>(n + 1));

        // Initialization: edit distance between empty string and word1[0...i-1] is i
        for (int i = 0; i <= m; i++) dp[i][0] = i;
        // Initialization: edit distance between empty string and word2[0...j-1] is j
        for (int j = 0; j <= n; j++) dp[0][j] = j;

        // Iterate through all possible prefixes of word1 and word2
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                // If the characters match, no operation is needed, inherit the distance from the previous prefixes
                if (word1[i - 1] == word2[j - 1]) {
                    dp[i][j] = dp[i - 1][j - 1];
                } else {
                    // If the characters don't match, consider three operations:
                    // 1. Insert: dp[i][j-1] + 1 (insert word2[j-1] into word1[0...i-1])
                    // 2. Delete: dp[i-1][j] + 1 (delete word1[i-1] from word1[0...i-1])
                    // 3. Replace: dp[i-1][j-1] + 1 (replace word1[i-1] with word2[j-1])
                    // Take the minimum of these three operations and add 1
                    dp[i][j] = min({
                        dp[i - 1][j],
                        dp[i][j - 1],
                        dp[i - 1][j - 1]
                    }) + 1;
                }
            }
        }

        // The edit distance between word1 and word2 is stored in dp[m][n]
        return dp[m][n];
    }
};

