function uniquePaths(m: number, n: number): number {
  // Initialize a 1D array 'row' of size 'n' with all elements set to 1.
  // This represents the number of paths to reach each cell in the first row (or initial row).
  let row: number[] = new Array(n).fill(1);

  // Iterate 'm - 1' times, representing the remaining rows (excluding the initial row).
  for (let i = 0; i < m - 1; i++) {
    // Create a new array 'newRow' of size 'n' filled with 1s.
    // This will store the number of paths for the current row being calculated.
    const newRow: number[] = new Array(n).fill(1);

    // Iterate through 'newRow' from right to left (from index 'n - 2' down to 0).
    for (let j = n - 2; j >= 0; j--) {
      // For each cell 'newRow[j]', the number of paths is the sum of the number of paths to the cell to its right ('newRow[j + 1]')
      // and the number of paths to the cell directly above it ('row[j]').
      newRow[j] = newRow[j + 1] + row[j];
    }

    // After calculating all values for 'newRow', update 'row' to be 'newRow',
    // so 'row' now represents the number of paths to each cell in the current row.
    row = newRow;
  }

  // After all rows have been processed, the value at 'row[0]' represents the number of paths to reach the bottom-right corner.
  return row[0];
}

