public static class Solution {
    public int uniquePaths(int m, int n) {
        // Initialize a 1D array 'row' of size 'n' with all 1s.
        // This represents the number of paths to reach each cell in the first row (or initial state).
        int[] row = new int[n];
        java.util.Arrays.fill(row, 1);

        // Iterate 'm - 1' times, calculating the number of paths for each subsequent row.
        // We start from the second row since the first row is already initialized.
        for (int i = 0; i < m - 1; i++) {         
           // Create a new array 'newRow' to store the number of paths for the current row.
           int[] newRow = new int[n];
           // Initialize 'newRow' with all 1s, representing the initial path count for each cell in the row.
           java.util.Arrays.fill(newRow, 1);

            // Iterate through 'newRow' from right to left (from 'n - 2' to 0).
            // This ensures that we are using the previously calculated values for the cells to the right.
            for (int j = n - 2; j >= 0; j--) {
                // The number of paths to reach 'newRow[j]' is the sum of the paths to its right ('newRow[j + 1]')
                // and the paths to the cell above it in the previous row ('row[j]').
                newRow[j] = newRow[j + 1] + row[j];
            }
            // Update 'row' with 'newRow' to prepare for the next iteration.
            // This effectively moves the current row's path counts to the 'previous row' for the next row's calculation.
            row = newRow;
        }

        // After the iterations, 'row[0]' contains the total number of unique paths from the top-left to the bottom-right corner.
        return row[0];
    }
}

