function canPartition(nums: number[]): boolean {
  // Calculate the total sum of the numbers in the input array.
  const total = nums.reduce((a, b) => a + b, 0);

  // If the total sum is odd, it's impossible to partition into two equal subsets.
  if (total % 2 !== 0) return false;

  // Initialize a set to store possible subset sums. Using a Set avoids duplicate sums.
  let dp = new Set<number>();
  // An empty set has a sum of 0, so we add 0 to the set initially.
  dp.add(0);

  // Calculate the target sum, which is half of the total sum.
  const target = total / 2;

  // Iterate through the numbers in the input array in reverse order.
  for (let i = nums.length - 1; i >= 0; i--) {
    // Create a new set to store the updated possible subset sums for the next iteration.
    const nextDP = new Set<number>();

    // Iterate through the current possible sums in the dp set.
    for (const t of dp) {
      // If adding the current number to the current sum equals the target, we found a partition.
      if (t + nums[i] === target) {
        return true;
      }

      // Add the new sum (current sum + current number) to the nextDP set.
      nextDP.add(t + nums[i]);
      // Also add the existing sum to the nextDP set (we might choose not to include the current number).
      nextDP.add(t);
    }

    // Update dp with nextDP for the next iteration.
    dp = nextDP;
  }

  // After iterating through all numbers, check if the target sum is in the dp set.
  return dp.has(target);
}

