public static class Solution {
    public boolean canPartition(int[] nums) {
        // Calculate the total sum of all numbers in the input array.
        int total = 0;
        for (int num : nums) {
            total += num;
        }

        // If the total sum is odd, the array cannot be partitioned into two equal sum subsets.
        if (total % 2 != 0) return false;

        // dp is a HashSet to store the possible subset sums.
        Set<Integer> dp = new HashSet<>();
        // Initialize dp with 0, representing an empty subset.
        dp.add(0);

        // Calculate the target sum, which is half of the total sum.
        int target = total / 2;

        // Iterate through the input array in reverse order.
        for (int i = nums.length - 1; i >= 0; i--) {
            // nextDP is a new HashSet to store the updated subset sums for the current iteration.
            Set<Integer> nextDP = new HashSet<>();

            // Iterate through the current dp set.
            for (int t : dp) {
                // If adding the current number to a sum in dp equals the target, return true immediately.
                if (t + nums[i] == target) {
                    return true;
                }

                // Add the sum including the current number to nextDP.
                nextDP.add(t + nums[i]);
                // Add the sum excluding the current number to nextDP.
                nextDP.add(t);
            }

            // Update dp to be nextDP for the next iteration.
            dp = nextDP;
        }

        // After iterating through all numbers, check if dp contains the target sum.
        return dp.contains(target);
    }
}

