class Solution {
public:
    bool canPartition(vector<int>& nums) {
        // Calculate the total sum of all numbers in the input vector.
        int total = 0;

        // Iterate through the numbers and add them to the total.
        for (int num : nums) {
            total += num;
        }

        // If the total sum is odd, it's impossible to partition into two equal subsets.
        if (total % 2 != 0) return false;

        // Use an unordered_set to store the possible subset sums we can achieve.
        unordered_set<int> dp;
        // Initialize the set with 0, representing an empty subset.
        dp.insert(0);

        // Calculate the target sum, which is half of the total sum.
        int target = total / 2;

        // Iterate through the numbers in reverse order.
        for (int i = nums.size() - 1; i >= 0; i--) {
            // Create a new set to store the next possible subset sums.
            unordered_set<int> nextDP;

            // Iterate through the current possible subset sums.
            for (int t : dp) {
                // If adding the current number to a subset sum equals the target, we found a partition.
                if (t + nums[i] == target) {
                    return true;
                }

                // Add the subset sum with and without the current number to the next set.
                nextDP.insert(t + nums[i]);
                nextDP.insert(t);
            }

            // Update the current set with the new possible subset sums.
            dp = nextDP;
        }

        // Check if the target sum exists in the final set, indicating a possible partition.
        return dp.count(target);
    }
};

