function insert(intervals: number[][], newInterval: number[]): number[][] {
    // Initialize the result array to store the merged intervals.
    const res: number[][] = [];

    // Iterate through the existing intervals.
    for (let i = 0; i < intervals.length; i++) {
        // Get the current interval.
        const curr = intervals[i];

        // Case 1: newInterval comes before the current interval.
        // If the newInterval ends before the current interval starts, there is no overlap.
        if (newInterval[1] < curr[0]) {
            // Add the newInterval to the result.
            res.push(newInterval);
            // Add the remaining intervals from the current index onwards and return.
            return res.concat(intervals.slice(i));
        }

        // Case 2: newInterval comes after the current interval.
        // If the newInterval starts after the current interval ends, there is no overlap.
        else if (newInterval[0] > curr[1]) {
            // Add the current interval to the result.
            res.push(curr);
        }

        // Case 3: Overlapping intervals.
        // If the intervals overlap, merge them.
        else {
            // Update the newInterval to be the merged interval.
            newInterval = [
                Math.min(newInterval[0], curr[0]), // Find the minimum start time.
                Math.max(newInterval[1], curr[1])  // Find the maximum end time.
            ];
        }
    }

    // If the newInterval hasn't been added yet (i.e., it overlaps with all intervals or comes after all of them),
    // add the merged newInterval to the result.
    res.push(newInterval);
    // Return the merged intervals.
    return res;
}

