                // Convert the list to an array and return.
                return result.toArray(new int[result.size()][]);
            }
            // Case 2: The newInterval comes completely after the current interval.
            // In this case, just add the current interval to the result.
            else if (newInterval[0] > current[1]) {
                result.add(current);
            }
            // Case 3: The newInterval overlaps with the current interval.
            // In this case, merge the newInterval with the current interval.
            else {
                // Update the start of the newInterval to be the minimum of the starts.
                newInterval[0] = Math.min(newInterval[0], current[0]);
                // Update the end of the newInterval to be the maximum of the ends.
                newInterval[1] = Math.max(newInterval[1], current[1]);
