function huffmanEncoding(text: string): Map<string, string> {
  // Create a frequency map to store the frequency of each character in the text.
  const freqMap = new Map<string, number>();
  // Iterate through each character in the input text.
  for (const char of text) {
    // Update the frequency of the character in the frequency map.
    freqMap.set(char, (freqMap.get(char) || 0) + 1);
  }

  // Create a min-heap (priority queue) of Huffman nodes from the frequency map.
  const heap: HuffmanNode[] = Array.from(freqMap.entries())
    .map(([char, freq]) => new HuffmanNode(char, freq));

  // Build the Huffman tree by repeatedly merging the two nodes with the smallest frequencies.
  while (heap.length > 1) {
    // Sort the heap to bring the nodes with the smallest frequencies to the front.
    heap.sort((a, b) => a.freq - b.freq);
    // Extract the two nodes with the smallest frequencies.
    const left = heap.shift()!;
    const right = heap.shift()!;
    // Create a new parent node with the sum of the frequencies of the two child nodes.
    const parent = new HuffmanNode('', left.freq + right.freq, left, right);
    // Push the new parent node back into the heap.
    heap.push(parent);
  }

  // Create a map to store the Huffman codes for each character.
  const codes = new Map<string, string>();
  // Define a recursive function to build the Huffman codes by traversing the Huffman tree.
  function buildCodes(node: HuffmanNode | null, code: string): void {
    // If the node is null, return.
    if (!node) return;
    // If the node is a leaf node (i.e., it has no children), then it represents a character.
    if (!node.left && !node.right) {
      // Store the Huffman code for the character in the codes map.
      codes.set(node.char, code || '0'); // Use '0' as default code if code is empty
      return;
    }
    // Recursively build the Huffman codes for the left and right subtrees.
    buildCodes(node.left, code + '0'); // Append '0' for left branch
    buildCodes(node.right, code + '1'); // Append '1' for right branch
  }
  // Start building the Huffman codes from the root node of the Huffman tree.
  buildCodes(heap[0], '');

  // Return the map of Huffman codes.
  return codes;
}

