    int frequency;
    HuffmanNode left;
    HuffmanNode right;

    HuffmanNode(char character, int frequency) {
        this.character = character;
        this.frequency = frequency;
        this.left = null;
        this.right = null;
    }
}

public static class Solution {

    public static Map<Character, String> huffmanEncoding(String text) {
        // Step 1: Calculate the frequency of each character in the input text.
        Map<Character, Integer> frequencyMap = new HashMap<>();
        for (char c : text.toCharArray()) {
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }

        // Step 2: Create a priority queue to store Huffman nodes, ordered by frequency.
        PriorityQueue<HuffmanNode> priorityQueue = new PriorityQueue<>(Comparator.comparingInt(node -> node.frequency));
        // Add each character and its frequency as a Huffman node to the priority queue.
        for (Map.Entry<Character, Integer> entry : frequencyMap.entrySet()) {
            priorityQueue.add(new HuffmanNode(entry.getKey(), entry.getValue()));
        }

        // Step 3: Build the Huffman tree.
        // While there is more than one node in the priority queue...
        while (priorityQueue.size() > 1) {
            // ...remove the two nodes with the lowest frequencies.
            HuffmanNode left = priorityQueue.poll();
            HuffmanNode right = priorityQueue.poll();
            // Create a new parent node with a frequency equal to the sum of the two nodes.
            HuffmanNode parent = new HuffmanNode('\0', left.frequency + right.frequency);
            // Set the left and right children of the parent node.
            parent.left = left;
            parent.right = right;
            // Add the parent node back to the priority queue.
            priorityQueue.add(parent);
        }

        // Step 4: Get the root of the Huffman tree.
        HuffmanNode root = priorityQueue.poll();
        // Create a map to store the Huffman codes for each character.
        Map<Character, String> huffmanCodes = new HashMap<>();
        // Build the Huffman codes by traversing the tree.
        buildHuffmanCodes(root, "", huffmanCodes);

        // Step 5: Return the map of Huffman codes.
        return huffmanCodes;
    }

    // Recursive helper function to build Huffman codes by traversing the tree.
    private static void buildHuffmanCodes(HuffmanNode node, String code, Map<Character, String> huffmanCodes) {
        // Base case: If the node is null, return.
        if (node == null) {
            return;
        }

        // If the node is a leaf node (i.e., it represents a character)...
        if (node.left == null && node.right == null) {
            // ...add the character and its Huffman code to the map.
            // If the code is empty, assign "0" as the code. Otherwise, use the generated code.
            huffmanCodes.put(node.character, code.isEmpty() ? "0" : code);
            return;
        }

        // Recursive step: Traverse the left and right subtrees, adding "0" and "1" to the code, respectively.
        buildHuffmanCodes(node.left, code + "0", huffmanCodes);
        buildHuffmanCodes(node.right, code + "1", huffmanCodes);
    }

    public static void main(String[] args) {
        String test = "hello world";
        Map<Character, String> codes = huffmanEncoding(test);
        System.out.println(codes);
    }
}

