function canCompleteCircuit(gas: number[], cost: number[]): number {
  // Calculate the total gas available by summing up the gas at each station.
  const totalGas = gas.reduce((a, b) => a + b, 0);
  // Calculate the total cost to travel between stations by summing up the cost for each segment.
  const totalCost = cost.reduce((a, b) => a + b, 0);

  // If the total gas is less than the total cost, it's impossible to complete the circuit.
  if (totalGas < totalCost) return -1;

  // Initialize 'total' to keep track of the current gas level in the tank.
  let total = 0;
  // Initialize 'res' to store the index of the potential starting station.
  let res = 0;

  // Iterate through each gas station.
  for (let i = 0; i < gas.length; i++) {
    // Update the current gas level by adding the gas at the current station and subtracting the cost to travel to the next station.
    total += gas[i] - cost[i];

    // If the current gas level becomes negative, it means that starting from the previous 'res' is not feasible.
    if (total < 0) {
      // Reset the current gas level to 0.
      total = 0;
      // Update 'res' to the next station (i + 1) as the potential starting point.
      res = i + 1;
    }
  }

  // After iterating through all stations, 'res' holds the index of the starting station.
  return res;
}

